def replace_question_marks(s):
    n = len(s)
    if n % 2 != 0:
        return ":("

    open_count = n // 2
    close_count = n // 2

    for char in s:
        if char == '(':
            open_count -= 1
        elif char == ')':
            close_count -= 1

    if open_count < 0 or close_count < 0:
        return ":("

    s = list(s)
    for i in range(n):
        if s[i] == '?':
            if open_count > 0:
                s[i] = '('
                open_count -= 1
            else:
                s[i] = ')'
                close_count -= 1

    # Check if the resulting string is a correct parenthesis sequence
    balance = 0
    for i in range(n):
        if s[i] == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return ":("

    if balance != 0:
        return ":("

    return ''.join(s)

